-- NovaTech Electronics: complete database (MySQL 8+ / MariaDB)
-- Fiscal years: FY2023-24 (Apr 2023-Mar 2024), FY2024-25 (Apr 2024-Mar 2025)
DROP DATABASE IF EXISTS novatech;
CREATE DATABASE novatech CHARACTER SET utf8mb4;
USE novatech;

CREATE TABLE fiscal_calendar (
    month_start DATE NOT NULL,
    fiscal_year_label VARCHAR(50) NOT NULL,
    fiscal_year_start INT NOT NULL,
    fiscal_quarter VARCHAR(50) NOT NULL,
    fiscal_month_num INT NOT NULL,
    calendar_year INT NOT NULL,
    calendar_month_num INT NOT NULL,
    month_name VARCHAR(50) NOT NULL,
    PRIMARY KEY (month_start)
) ENGINE=InnoDB;

CREATE TABLE departments (
    department_id INT NOT NULL,
    department_name VARCHAR(80) NOT NULL,
    division VARCHAR(50) NOT NULL,
    PRIMARY KEY (department_id)
) ENGINE=InnoDB;

CREATE TABLE channels (
    channel_id INT NOT NULL,
    channel_name VARCHAR(50) NOT NULL,
    PRIMARY KEY (channel_id)
) ENGINE=InnoDB;

CREATE TABLE warehouses (
    warehouse_id INT NOT NULL,
    warehouse_name VARCHAR(100) NOT NULL,
    city VARCHAR(50) NOT NULL,
    region VARCHAR(50) NOT NULL,
    PRIMARY KEY (warehouse_id)
) ENGINE=InnoDB;

CREATE TABLE products (
    product_id INT NOT NULL,
    product_name VARCHAR(120) NOT NULL,
    category VARCHAR(50) NOT NULL,
    unit_cost DECIMAL(14,2) NOT NULL,
    unit_price DECIMAL(14,2) NOT NULL,
    launch_date DATE NOT NULL,
    PRIMARY KEY (product_id)
) ENGINE=InnoDB;

CREATE TABLE stores (
    store_id INT NOT NULL,
    store_name VARCHAR(100) NOT NULL,
    channel_id INT NOT NULL,
    city VARCHAR(50),
    region VARCHAR(50) NOT NULL,
    open_date DATE NOT NULL,
    PRIMARY KEY (store_id),
    FOREIGN KEY (channel_id) REFERENCES channels(channel_id)
) ENGINE=InnoDB;

CREATE TABLE customers (
    customer_id INT NOT NULL,
    customer_name VARCHAR(100) NOT NULL,
    email VARCHAR(120) NOT NULL,
    segment VARCHAR(50) NOT NULL,
    region VARCHAR(50) NOT NULL,
    signup_date DATE NOT NULL,
    PRIMARY KEY (customer_id)
) ENGINE=InnoDB;

CREATE TABLE suppliers (
    supplier_id INT NOT NULL,
    supplier_name VARCHAR(100) NOT NULL,
    region VARCHAR(50) NOT NULL,
    specialty VARCHAR(50) NOT NULL,
    reliability_score DECIMAL(3,2) NOT NULL,
    payment_terms_days INT NOT NULL,
    PRIMARY KEY (supplier_id)
) ENGINE=InnoDB;

CREATE TABLE raw_materials (
    material_id INT NOT NULL,
    material_name VARCHAR(100) NOT NULL,
    material_category VARCHAR(50) NOT NULL,
    unit VARCHAR(50) NOT NULL,
    standard_unit_cost DECIMAL(14,2) NOT NULL,
    PRIMARY KEY (material_id)
) ENGINE=InnoDB;

CREATE TABLE bill_of_materials (
    product_id INT NOT NULL,
    material_id INT NOT NULL,
    qty_per_unit DECIMAL(8,2) NOT NULL,
    PRIMARY KEY (product_id, material_id),
    FOREIGN KEY (material_id) REFERENCES raw_materials(material_id),
    FOREIGN KEY (product_id) REFERENCES products(product_id)
) ENGINE=InnoDB;

CREATE TABLE orders (
    order_id INT NOT NULL,
    customer_id INT NOT NULL,
    store_id INT NOT NULL,
    channel_id INT NOT NULL,
    order_date DATE NOT NULL,
    order_status VARCHAR(50) NOT NULL,
    payment_method VARCHAR(50) NOT NULL,
    PRIMARY KEY (order_id),
    FOREIGN KEY (channel_id) REFERENCES channels(channel_id),
    FOREIGN KEY (store_id) REFERENCES stores(store_id),
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
) ENGINE=InnoDB;

CREATE TABLE order_details (
    order_detail_id INT NOT NULL,
    order_id INT NOT NULL,
    product_id INT NOT NULL,
    quantity INT NOT NULL,
    unit_price DECIMAL(14,2) NOT NULL,
    discount_pct DECIMAL(4,2) NOT NULL,
    PRIMARY KEY (order_detail_id),
    FOREIGN KEY (product_id) REFERENCES products(product_id),
    FOREIGN KEY (order_id) REFERENCES orders(order_id)
) ENGINE=InnoDB;

CREATE TABLE purchase_orders (
    po_id INT NOT NULL,
    supplier_id INT NOT NULL,
    material_id INT NOT NULL,
    order_date DATE NOT NULL,
    expected_delivery_date DATE NOT NULL,
    actual_delivery_date DATE,
    quantity DECIMAL(12,0) NOT NULL,
    unit_cost DECIMAL(14,2) NOT NULL,
    status VARCHAR(50) NOT NULL,
    PRIMARY KEY (po_id),
    FOREIGN KEY (material_id) REFERENCES raw_materials(material_id),
    FOREIGN KEY (supplier_id) REFERENCES suppliers(supplier_id)
) ENGINE=InnoDB;

CREATE TABLE production_orders (
    prod_order_id INT NOT NULL,
    product_id INT NOT NULL,
    production_date DATE NOT NULL,
    quantity_produced INT NOT NULL,
    labor_cost DECIMAL(14,2) NOT NULL,
    overhead_cost DECIMAL(14,2) NOT NULL,
    material_cost DECIMAL(14,2) NOT NULL,
    defect_units INT NOT NULL,
    PRIMARY KEY (prod_order_id),
    FOREIGN KEY (product_id) REFERENCES products(product_id)
) ENGINE=InnoDB;

CREATE TABLE inventory_snapshots (
    snapshot_id INT NOT NULL,
    snapshot_date DATE NOT NULL,
    product_id INT NOT NULL,
    location_type VARCHAR(50) NOT NULL,
    location_id INT,
    quantity_on_hand INT NOT NULL,
    PRIMARY KEY (snapshot_id),
    FOREIGN KEY (product_id) REFERENCES products(product_id)
) ENGINE=InnoDB;

CREATE TABLE employees (
    employee_id INT NOT NULL,
    employee_name VARCHAR(100) NOT NULL,
    department_id INT NOT NULL,
    role VARCHAR(80) NOT NULL,
    monthly_salary DECIMAL(14,2) NOT NULL,
    hire_date DATE NOT NULL,
    termination_date DATE,
    PRIMARY KEY (employee_id),
    FOREIGN KEY (department_id) REFERENCES departments(department_id)
) ENGINE=InnoDB;

CREATE TABLE department_budget (
    budget_id INT NOT NULL,
    department_id INT NOT NULL,
    month DATE NOT NULL,
    cost_category VARCHAR(50) NOT NULL,
    budget_amount DECIMAL(14,2) NOT NULL,
    PRIMARY KEY (budget_id),
    FOREIGN KEY (department_id) REFERENCES departments(department_id)
) ENGINE=InnoDB;

CREATE TABLE department_actuals (
    actual_id INT NOT NULL,
    department_id INT NOT NULL,
    month DATE NOT NULL,
    cost_category VARCHAR(50) NOT NULL,
    actual_amount DECIMAL(14,2) NOT NULL,
    PRIMARY KEY (actual_id),
    FOREIGN KEY (department_id) REFERENCES departments(department_id)
) ENGINE=InnoDB;

CREATE TABLE forecast_monthly (
    forecast_id INT NOT NULL,
    forecast_month DATE NOT NULL,
    product_category VARCHAR(50) NOT NULL,
    channel_id INT NOT NULL,
    forecast_units INT NOT NULL,
    forecast_revenue DECIMAL(14,2) NOT NULL,
    forecast_date DATE NOT NULL,
    PRIMARY KEY (forecast_id),
    FOREIGN KEY (channel_id) REFERENCES channels(channel_id)
) ENGINE=InnoDB;

