CREATE INDEX idx_orders_date ON orders(order_date);
CREATE INDEX idx_orders_customer ON orders(customer_id);
CREATE INDEX idx_orders_store ON orders(store_id);
CREATE INDEX idx_od_order ON order_details(order_id);
CREATE INDEX idx_od_product ON order_details(product_id);
CREATE INDEX idx_prod_date ON production_orders(production_date);
CREATE INDEX idx_po_material ON purchase_orders(material_id);
CREATE INDEX idx_po_supplier ON purchase_orders(supplier_id);
CREATE INDEX idx_actuals_month ON department_actuals(month);
CREATE INDEX idx_budget_month ON department_budget(month);
CREATE INDEX idx_emp_dept ON employees(department_id);
